"""Construct Binary Tree from Preorder and Inorder Traversal.

Preorder hands out roots in order; the index of a root inside inorder splits the
remaining values into the left and right subtrees. A value->index map keeps each
split O(1).

Time: O(n)   Space: O(n)
"""
from typing import List

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]):
        position = {value: i for i, value in enumerate(inorder)}
        self._cursor = 0

        def build(lo: int, hi: int):
            if lo > hi:
                return None
            value = preorder[self._cursor]
            self._cursor += 1
            node = TreeNode(value)
            mid = position[value]
            node.left = build(lo, mid - 1)
            node.right = build(mid + 1, hi)
            return node

        return build(0, len(inorder) - 1)
